/**
 * Regenerates src/data/places/heroes.ts from the photos present in public/images/places/.
 *   node scripts/update-place-heroes.mjs
 */
import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const dir = path.join(root, "public", "images", "places");
const ids = fs.existsSync(dir)
  ? fs.readdirSync(dir).filter((f) => f.endsWith(".jpg")).map((f) => f.replace(/\.jpg$/, "")).sort()
  : [];

const body = `/**
 * Hero photos for place pages. Generated by \`node scripts/update-place-heroes.mjs\` from the files in
 * public/images/places/ (one landscape JPEG per place, named after the place id). Do not edit by hand.
 * Sources are listed in docs/place-hero-sources.md.
 */
const WITH_HERO = new Set<string>([
${ids.map((id) => `  "${id}",`).join("\n")}
]);

/** Path of the place's hero photo, or undefined when it has none (the page then falls back to a trip-day photo). */
export const placeHero = (id: string): string | undefined => (WITH_HERO.has(id) ? \`/images/places/\${id}.jpg\` : undefined);
`;
fs.writeFileSync(path.join(root, "src", "data", "places", "heroes.ts"), body);
console.log(`heroes.ts: ${ids.length} places`);
